import{_ as t,o as a,c as e,a2 as o}from"./chunks/framework.A5mep7Fe.js";const _=JSON.parse('{"title":"🔗 03 · 内推与招聘渠道","description":"","frontmatter":{},"headers":[],"relativePath":"10-职业发展与资源/03-内推与招聘渠道.md","filePath":"10-职业发展与资源/03-内推与招聘渠道.md","lastUpdated":1786806808000}'),r={name:"10-职业发展与资源/03-内推与招聘渠道.md"};function i(n,l,s,d,u,h){return a(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="🔗-03-·-内推与招聘渠道" tabindex="-1">🔗 03 · 内推与招聘渠道 <a class="header-anchor" href="#🔗-03-·-内推与招聘渠道" aria-label="Permalink to &quot;🔗 03 · 内推与招聘渠道&quot;">​</a></h1><blockquote><p>内推是 AI 岗最高效的渠道——简历直达、反馈快、通过率高。本篇汇总渠道与内推技巧。</p></blockquote><hr><h2 id="一、内推-首选" tabindex="-1">一、内推（首选） <a class="header-anchor" href="#一、内推-首选" aria-label="Permalink to &quot;一、内推（首选）&quot;">​</a></h2><ul><li><strong>为什么有效</strong>：绕过海选、HR 优先看、可问进展</li><li><strong>怎么找内推</strong>： <ul><li>校友/前同事/朋友（最稳）</li><li>技术社区（GitHub/知乎/掘金/微信公众号的「内推帖」）</li><li>牛客网内推板块</li><li>LinkedIn / 脉脉 礼貌私信在职员工</li></ul></li><li><strong>内推话术</strong>：简短介绍背景 + 求职意向 + 附件简历 + 「方便帮忙内推吗，感谢」</li><li><strong>注意</strong>：内推不等于保送，仍靠实力；礼貌、及时反馈进度</li></ul><h2 id="二、招聘平台" tabindex="-1">二、招聘平台 <a class="header-anchor" href="#二、招聘平台" aria-label="Permalink to &quot;二、招聘平台&quot;">​</a></h2><ul><li><strong>国内</strong>：BOSS 直聘（响应快）、猎聘（中高端）、拉勾（互联网）、牛客（校招/实习）</li><li><strong>海外</strong>：LinkedIn、Indeed、Levels.fyi（薪资参考）</li><li><strong>垂直</strong>：AI 专场招聘、各公司官网招聘页</li></ul><h2 id="三、社区与被动机会" tabindex="-1">三、社区与被动机会 <a class="header-anchor" href="#三、社区与被动机会" aria-label="Permalink to &quot;三、社区与被动机会&quot;">​</a></h2><ul><li><strong>GitHub / 技术博客</strong>：优质产出会被猎头/技术 leader 主动找</li><li><strong>Kaggle / 竞赛</strong>：Top 成绩是强背书</li><li><strong>开源贡献</strong>：在知名 AI 项目提 PR，建立声誉</li><li><strong>技术大会/Meetup</strong>：线下建立人脉</li></ul><h2 id="四、校招专项" tabindex="-1">四、校招专项 <a class="header-anchor" href="#四、校招专项" aria-label="Permalink to &quot;四、校招专项&quot;">​</a></h2><ul><li>暑期实习 → 转正（最稳路径）</li><li>秋招（7-10月）/ 春招（3-5月）提前准备</li><li>关注「AI 专场笔面经」刷熟套路</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q：没熟人怎么内推？</strong></p><blockquote><p>用牛客/技术社区的内推帖、脉脉礼貌联系目标公司员工、参加活动。内推核心是「让对方愿意帮你」，礼貌+清晰背景+好简历是基础。</p></blockquote><p><strong>Q：海投 vs 精投？</strong></p><blockquote><p>校招可适度海投练手；社招建议精投（研究岗位匹配度），每个都针对性改简历，命中率远高于撒网。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-刷题与学习资源">04-刷题与学习资源</a></p>',18)])])}const g=t(r,[["render",i]]);export{_ as __pageData,g as default};
